script:
(function () {
  'use strict';
  // Home equity loan vs auto loan for buying a car: cost of borrowing after tax, and the home at risk.
  //   Amount needed = price - down payment + sales tax (price x rate) + title/registration fees.
  //   Auto loan = amount needed + lender fees (when added to the loan; otherwise paid in cash).
  //   Home equity loan = amount needed + closing costs (when added to the loan; otherwise paid in cash).
  //   Payment: M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%).
  //   Cost of borrowing = total interest + fees or closing costs - tax saving.
  //   Combined loan-to-value = (mortgage balance + home equity loan) / home value.
  //   Car value after y years = price x (1 - yearly depreciation)^y.
  // TAX RULES (tax year 2026, scheduled to apply for 2025-2028 only):
  //   Home equity interest: not deductible when the money buys a car — IRS Pub. 936 (2025): interest on a
  //   loan secured by your home is not deductible to the extent the proceeds weren't used to buy, build
  //   or substantially improve the home. So the home equity loan gets no tax saving here.
  //   Car loan interest deduction (Schedule 1-A, Part IV; IRS OBBBA guidance): loan secured by a lien on
  //   a new, US-assembled, personal-use vehicle under 14,000 lb GVWR, originated after 2024.
  //   Deduction per year = min(interest, $10,000) - $200 for each $1,000 (or part) of MAGI above
  //   $100,000 ($200,000 joint), never below 0. Saving = deduction x marginal rate.
  //   Assumes the loan starts in January 2026, so loan years 1-3 = tax years 2026-2028.
  var CAR_INT_CAP = 10000, PHASE_START = { single: 100000, joint: 200000 }, PHASE_STEP = 200, LAST_TAX_YEAR = 2028, START_YEAR = 2026;
  // Verified in Node (scratchpad tests/auto5): $35,000 car, $5,000 down, 6% tax, $800 fees -> $32,900
  //   needed; auto loan at 7% for 60 months = $651.46/mo, interest $6,187.57 (closed form); home equity
  //   $33,400 (with $500 closing costs) at 8% for 120 months = $405.23/mo; year-1 car-loan interest
  //   $2,122.59 with MAGI $90,000 -> fully deductible, 3-year saving at 22% = $1,122.65; MAGI $105,500 single ->
  //   $1,200 yearly reduction (6 steps, Schedule 1-A rounds up) -> $330.65; interest above $10,000 is capped; 0% rates
  //   give no interest and no NaN; blank or negative input shows an error.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Yearly interest and end-of-year balances.
  function amortize(loan, annualRate, months) {
    var pay = monthlyPayment(loan, annualRate, months), i = annualRate / 12, bal = loan;
    var years = [], total = 0, yInt = 0;
    for (var m = 1; m <= months; m++) {
      var interest = bal * i;
      bal -= pay - interest;
      if (bal < 0.005 || m === months) bal = 0;
      total += interest; yInt += interest;
      if (m % 12 === 0 || m === months) { years.push({ interest: yInt, balance: bal }); yInt = 0; }
    }
    return { payment: pay, totalInterest: total, years: years };
  }

  function carDeduction(interest, magi, status) {
    var over = Math.max(0, magi - PHASE_START[status]);
    var cut = Math.ceil(over / 1000) * PHASE_STEP;
    return Math.max(0, Math.min(interest, CAR_INT_CAP) - cut);
  }

  function clearResults() {
    ['heVerdict', 'heAutoCost', 'heHeCost', 'heAutoPay', 'heHePay', 'heAutoInt', 'heHeInt', 'heTaxSaving',
     'heCltv', 'heTail'].forEach(function (id) { setText(id, '–'); });
    setText('heVerdictLabel', 'Cheaper option');
    el('heTailBox').hidden = true;
    el('heCltvBox').hidden = true;
    el('heYears').innerHTML = '';
  }

  function update() {
    var price = read('hePrice'), down = read('heDown', true), taxRate = read('heTaxRate', true), fees = read('heFees', true),
        aRate = read('heAutoRate'), aTerm = read('heAutoTerm'), aFees = read('heAutoFees', true),
        hRate = read('heHeRate'), hTerm = read('heHeTerm'), hCost = read('heClosing', true),
        homeValue = read('heHomeValue', true), mortgage = read('heMortgage', true), dep = read('heDep', true),
        magi = read('heMagi', true), marginal = read('heMarginal', true), status = el('heStatus').value,
        qualifies = el('heQualifies').checked, rollFees = el('heRollFees').checked;
    var error = el('heError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(aRate) || aRate < 0 || aRate > 40) msg = 'Enter an auto loan rate from 0% to 40%.';
    else if (isNaN(aTerm) || aTerm < 1 || aTerm > 120 || aTerm % 1 !== 0) msg = 'Enter an auto loan term of 1 to 120 whole months.';
    else if (isNaN(hRate) || hRate < 0 || hRate > 40) msg = 'Enter a home equity rate from 0% to 40%.';
    else if (isNaN(hTerm) || hTerm < 1 || hTerm > 360 || hTerm % 1 !== 0) msg = 'Enter a home equity loan term of 1 to 360 whole months.';
    else if ([down, taxRate, fees, aFees, hCost, homeValue, mortgage, dep, magi, marginal].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (dep >= 100) msg = 'Enter a yearly depreciation below 100%.';
    else if (marginal > 50) msg = 'Enter a federal tax rate of 50% or less.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    var needed = price - down + price * taxRate / 100 + fees;
    if (needed <= 0.005) { error.hidden = false; error.textContent = 'Your down payment covers the whole cost, so there is nothing to borrow.'; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var aLoan = needed + (rollFees ? aFees : 0), hLoan = needed + (rollFees ? hCost : 0);
    var a = amortize(aLoan, aRate / 100, aTerm), h = amortize(hLoan, hRate / 100, hTerm);
    var saving = 0;
    if (qualifies) {
      a.years.forEach(function (y, idx) {
        if (START_YEAR + idx <= LAST_TAX_YEAR) saving += carDeduction(y.interest, magi, status) * marginal / 100;
      });
    }
    var aCost = a.totalInterest + aFees - saving, hCostTotal = h.totalInterest + hCost, d = aCost - hCostTotal;
    if (Math.abs(d) < 0.5) { setText('heVerdictLabel', 'Cheaper option'); setText('heVerdict', 'About the same'); }
    else { setText('heVerdictLabel', d > 0 ? 'Home equity loan saves' : 'Auto loan saves'); setText('heVerdict', money.format(Math.abs(d))); }
    setText('heAutoCost', money.format(aCost));
    setText('heHeCost', money.format(hCostTotal));
    setText('heAutoPay', money.format(a.payment));
    setText('heHePay', money.format(h.payment));
    setText('heAutoInt', money.format(a.totalInterest));
    setText('heHeInt', money.format(h.totalInterest));
    setText('heTaxSaving', qualifies ? money.format(saving) : 'Not claimed');

    if (homeValue > 0) {
      el('heCltvBox').hidden = false;
      setText('heCltv', ((mortgage + hLoan) / homeValue * 100).toFixed(1) + '%');
    } else {
      el('heCltvBox').hidden = true;
      setText('heCltv', '–');
    }
    if (hTerm > aTerm) {
      var k = Math.ceil(aTerm / 12) - 1;
      var bal = k < h.years.length ? h.years[k].balance : 0;
      el('heTailBox').hidden = !(bal > 0.5);
      setText('heTail', money.format(bal));
    } else {
      el('heTailBox').hidden = true;
    }

    var n = Math.max(a.years.length, h.years.length), html = [];
    for (var y = 0; y < n; y++) {
      var value = price * Math.pow(1 - dep / 100, y + 1);
      var ab = y < a.years.length ? a.years[y].balance : 0, hb = y < h.years.length ? h.years[y].balance : 0;
      var flag = hb > value ? ' class="font-semibold"' : '';
      html.push('<tr' + flag + '><td>' + (y + 1) + '</td><td>' + money0.format(value) + '</td><td>' + money0.format(ab) +
        '</td><td>' + money0.format(hb) + '</td></tr>');
    }
    el('heYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('heForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
